     1→//! Helpers for dealing with Precompiles.
     2→
     3→use crate::{Database, EvmInternals};
     4→use alloc::{borrow::Cow, boxed::Box, string::String, sync::Arc};
     5→use alloy_consensus::transaction::Either;
     6→use alloy_primitives::{
     7→    map::{HashMap, HashSet},
     8→    Address, Bytes, U256,
     9→};
    10→use core::fmt::Debug;
    11→use revm::{
    12→    context::LocalContextTr,
    13→    handler::{EthPrecompiles, PrecompileProvider},
    14→    interpreter::{CallInput, CallInputs, Gas, InstructionResult, InterpreterResult},
    15→    precompile::{PrecompileError, PrecompileFn, PrecompileId, PrecompileResult, Precompiles},
    16→    Context, Journal,
    17→};
    18→
    19→/// A mapping of precompile contracts that can be either static (builtin) or dynamic.
    20→///
    21→/// This is an optimization that allows us to keep using the static precompiles
    22→/// until we need to modify them, at which point we convert to the dynamic representation.
    23→#[derive(Clone)]
    24→pub struct PrecompilesMap {
    25→    /// The wrapped precompiles in their current representation.
    26→    precompiles: PrecompilesKind,
    27→    /// An optional dynamic precompile loader that can lookup precompiles dynamically.
    28→    lookup: Option<Arc<dyn PrecompileLookup>>,
    29→}
    30→
    31→impl PrecompilesMap {
    32→    /// Creates the [`PrecompilesMap`] from a static reference.
    33→    pub fn from_static(precompiles: &'static Precompiles) -> Self {
    34→        Self::new(Cow::Borrowed(precompiles))
    35→    }
    36→
    37→    /// Creates a new set of precompiles for a spec.
    38→    pub fn new(precompiles: Cow<'static, Precompiles>) -> Self {
    39→        Self { precompiles: PrecompilesKind::Builtin(precompiles), lookup: None }
    40→    }
    41→
    42→    /// Maps a precompile at the given address using the provided function.
    43→    pub fn map_precompile<F>(&mut self, address: &Address, f: F)
    44→    where
    45→        F: FnOnce(DynPrecompile) -> DynPrecompile + Send + Sync + 'static,
    46→    {
    47→        let dyn_precompiles = self.ensure_dynamic_precompiles();
    48→
    49→        // get the current precompile at the address
    50→        if let Some(dyn_precompile) = dyn_precompiles.inner.remove(address) {
    51→            // apply the transformation function
    52→            let transformed = f(dyn_precompile);
    53→
    54→            // update the precompile at the address
    55→            dyn_precompiles.inner.insert(*address, transformed);
    56→        }
    57→    }
    58→
    59→    /// Maps all precompiles using the provided function.
    60→    pub fn map_precompiles<F>(&mut self, f: F)
    61→    where
    62→        F: FnMut(&Address, DynPrecompile) -> DynPrecompile,
    63→    {
    64→        self.map_precompiles_filtered(f, |_, _| true);
    65→    }
    66→
    67→    /// Maps all pure precompiles using the provided function.
    68→    ///
    69→    /// This is a variant of [`Self::map_precompiles`] that only applies the transformation
    70→    /// to precompiles that are pure, see [`Precompile::is_pure`].
    71→    pub fn map_pure_precompiles<F>(&mut self, f: F)
    72→    where
    73→        F: FnMut(&Address, DynPrecompile) -> DynPrecompile,
    74→    {
    75→        self.map_precompiles_filtered(f, |_, precompile| precompile.is_pure());
    76→    }
    77→
    78→    /// Internal helper to map precompiles with an optional filter.
    79→    ///
    80→    /// The `filter` decides whether to apply the mapping function `f` to a given
    81→    /// precompile. If the filter returns `false`, the original precompile is kept.
    82→    #[inline]
    83→    fn map_precompiles_filtered<F, P>(&mut self, mut f: F, mut filter: P)
    84→    where
    85→        F: FnMut(&Address, DynPrecompile) -> DynPrecompile,
    86→        P: FnMut(&Address, &DynPrecompile) -> bool,
    87→    {
    88→        let dyn_precompiles = self.ensure_dynamic_precompiles();
    89→
    90→        // apply the transformation to each precompile
    91→        let entries = dyn_precompiles.inner.drain();
    92→        let mut new_map =
    93→            HashMap::with_capacity_and_hasher(entries.size_hint().0, Default::default());
    94→        for (addr, precompile) in entries {
    95→            if filter(&addr, &precompile) {
    96→                let transformed = f(&addr, precompile);
    97→                new_map.insert(addr, transformed);
    98→            } else {
    99→                new_map.insert(addr, precompile);
   100→            }
   101→        }
   102→
   103→        dyn_precompiles.inner = new_map;
   104→    }
   105→
   106→    /// Applies a transformation to the precompile at the given address.
   107→    ///
   108→    /// This method allows you to add, update, or remove a precompile by applying a closure
   109→    /// to the existing precompile (if any) at the specified address.
   110→    ///
   111→    /// # Behavior
   112→    ///
   113→    /// The closure receives:
   114→    /// - `Some(precompile)` if a precompile exists at the address
   115→    /// - `None` if no precompile exists at the address
   116→    ///
   117→    /// Based on what the closure returns:
   118→    /// - `Some(precompile)` - Insert or replace the precompile at the address
   119→    /// - `None` - Remove the precompile from the address (if it exists)
   120→    ///
   121→    /// # Examples
   122→    ///
   123→    /// ```ignore
   124→    /// // Add a new precompile
   125→    /// precompiles.apply_precompile(&address, |_| Some(my_precompile));
   126→    ///
   127→    /// // Update an existing precompile
   128→    /// precompiles.apply_precompile(&address, |existing| {
   129→    ///     existing.map(|p| wrap_with_logging(p))
   130→    /// });
   131→    ///
   132→    /// // Remove a precompile
   133→    /// precompiles.apply_precompile(&address, |_| None);
   134→    ///
   135→    /// // Conditionally update
   136→    /// precompiles.apply_precompile(&address, |existing| {
   137→    ///     if let Some(p) = existing {
   138→    ///         Some(modify_precompile(p))
   139→    ///     } else {
   140→    ///         Some(create_default_precompile())
   141→    ///     }
   142→    /// });
   143→    /// ```
   144→    pub fn apply_precompile<F>(&mut self, address: &Address, f: F)
   145→    where
   146→        F: FnOnce(Option<DynPrecompile>) -> Option<DynPrecompile>,
   147→    {
   148→        let dyn_precompiles = self.ensure_dynamic_precompiles();
   149→        let current = dyn_precompiles.inner.get(address).cloned();
   150→
   151→        // apply the transformation function
   152→        let result = f(current);
   153→
   154→        match result {
   155→            Some(transformed) => {
   156→                // insert the transformed precompile
   157→                dyn_precompiles.inner.insert(*address, transformed);
   158→                dyn_precompiles.addresses.insert(*address);
   159→            }
   160→            None => {
   161→                // remove the precompile if the transformation returned None
   162→                dyn_precompiles.inner.remove(address);
   163→                dyn_precompiles.addresses.remove(address);
   164→            }
   165→        }
   166→    }
   167→
   168→    /// Builder-style method that maps a precompile at the given address using the provided
   169→    /// function.
   170→    ///
   171→    /// This is a consuming version of [`map_precompile`](Self::map_precompile) that returns `Self`.
   172→    pub fn with_mapped_precompile<F>(mut self, address: &Address, f: F) -> Self
   173→    where
   174→        F: FnOnce(DynPrecompile) -> DynPrecompile + Send + Sync + 'static,
   175→    {
   176→        self.map_precompile(address, f);
   177→        self
   178→    }
   179→
   180→    /// Builder-style method that maps all precompiles using the provided function.
   181→    ///
   182→    /// This is a consuming version of [`map_precompiles`](Self::map_precompiles) that returns
   183→    /// `Self`.
   184→    pub fn with_mapped_precompiles<F>(mut self, f: F) -> Self
   185→    where
   186→        F: FnMut(&Address, DynPrecompile) -> DynPrecompile,
   187→    {
   188→        self.map_precompiles(f);
   189→        self
   190→    }
   191→
   192→    /// Builder-style method that applies a transformation to the precompile at the given address.
   193→    ///
   194→    /// This is a consuming version of [`apply_precompile`](Self::apply_precompile) that returns
   195→    /// `Self`. See [`apply_precompile`](Self::apply_precompile) for detailed behavior and
   196→    /// examples.
   197→    pub fn with_applied_precompile<F>(mut self, address: &Address, f: F) -> Self
   198→    where
   199→        F: FnOnce(Option<DynPrecompile>) -> Option<DynPrecompile>,
   200→    {
   201→        self.apply_precompile(address, f);
   202→        self
   203→    }
   204→
   205→    /// Sets a dynamic precompile lookup function that is called for addresses not found
   206→    /// in the static precompile map.
   207→    ///
   208→    /// This method allows you to provide runtime-resolved precompiles that aren't known
   209→    /// at initialization time. The lookup function is called whenever a precompile check
   210→    /// is performed for an address that doesn't exist in the main precompile map.
   211→    ///
   212→    /// # Important Notes
   213→    ///
   214→    /// - **Priority**: Static precompiles take precedence. The lookup function is only called if
   215→    ///   the address is not found in the main precompile map.
   216→    /// - **Gas accounting**: Addresses resolved through this lookup are always treated as cold,
   217→    ///   meaning they incur cold access costs even on repeated calls within the same transaction.
   218→    ///   See also [`PrecompileProvider::warm_addresses`].
   219→    /// - **Performance**: The lookup function is called on every precompile check for
   220→    ///   non-registered addresses, so it should be efficient.
   221→    ///
   222→    /// # Example
   223→    ///
   224→    /// ```ignore
   225→    /// precompiles.set_precompile_lookup(|address| {
   226→    ///     // Dynamically resolve precompiles based on address pattern
   227→    ///     if address.as_slice().starts_with(&[0xDE, 0xAD]) {
   228→    ///         Some(DynPrecompile::new(|input| {
   229→    ///             // Custom precompile logic
   230→    ///             Ok(PrecompileOutput {
   231→    ///                 gas_used: 100,
   232→    ///                 bytes: Bytes::from("dynamic precompile"),
   233→    ///             })
   234→    ///         }))
   235→    ///     } else {
   236→    ///         None
   237→    ///     }
   238→    /// });
   239→    /// ```
   240→    pub fn set_precompile_lookup<L>(&mut self, lookup: L)
   241→    where
   242→        L: PrecompileLookup + 'static,
   243→    {
   244→        self.lookup = Some(Arc::new(lookup));
   245→    }
   246→
   247→    /// Builder-style method to set a dynamic precompile lookup function.
   248→    ///
   249→    /// This is a consuming version of [`set_precompile_lookup`](Self::set_precompile_lookup)
   250→    /// that returns `Self` for method chaining.
   251→    ///
   252→    /// See [`set_precompile_lookup`](Self::set_precompile_lookup) for detailed behavior,
   253→    /// important notes, and examples.
   254→    pub fn with_precompile_lookup<L>(mut self, lookup: L) -> Self
   255→    where
   256→        L: PrecompileLookup + 'static,
   257→    {
   258→        self.set_precompile_lookup(lookup);
   259→        self
   260→    }
   261→
   262→    /// Consumes the type and returns a set of [`DynPrecompile`].
   263→    pub fn into_dyn_precompiles(mut self) -> DynPrecompiles {
   264→        self.ensure_dynamic_precompiles();
   265→        match self.precompiles {
   266→            PrecompilesKind::Dynamic(dynamic) => dynamic,
   267→            _ => unreachable!("We just ensured that this is a Dynamic variant"),
   268→        }
   269→    }
   270→
   271→    /// Ensures that precompiles are in their dynamic representation.
   272→    /// If they are already dynamic, this is a no-op.
   273→    /// Returns a mutable reference to the dynamic precompiles.
   274→    pub fn ensure_dynamic_precompiles(&mut self) -> &mut DynPrecompiles {
   275→        if let PrecompilesKind::Builtin(ref precompiles_cow) = self.precompiles {
   276→            let mut dynamic = DynPrecompiles::default();
   277→
   278→            let static_precompiles = match precompiles_cow {
   279→                Cow::Borrowed(static_ref) => static_ref,
   280→                Cow::Owned(owned) => owned,
   281→            };
   282→
   283→            for (&addr, pc) in static_precompiles.inner().iter() {
   284→                dynamic.inner.insert(addr, DynPrecompile::from(*pc.precompile()));
   285→                dynamic.addresses.insert(addr);
   286→            }
   287→
   288→            self.precompiles = PrecompilesKind::Dynamic(dynamic);
   289→        }
   290→
   291→        match &mut self.precompiles {
   292→            PrecompilesKind::Dynamic(dynamic) => dynamic,
   293→            _ => unreachable!("We just ensured that this is a Dynamic variant"),
   294→        }
   295→    }
   296→
   297→    /// Returns an iterator over the [`PrecompileId`]s of the installed precompiles.
   298→    pub fn identifiers(&self) -> impl Iterator<Item = &PrecompileId> {
   299→        match &self.precompiles {
   300→            PrecompilesKind::Builtin(precompiles) => {
   301→                Either::Left(precompiles.inner().values().map(|p| p.precompile_id()))
   302→            }
   303→            PrecompilesKind::Dynamic(dyn_precompiles) => {
   304→                Either::Right(dyn_precompiles.inner.values().map(|p| p.precompile_id()))
   305→            }
   306→        }
   307→    }
   308→
   309→    /// Returns an iterator over references to precompile addresses.
   310→    pub fn addresses(&self) -> impl Iterator<Item = &Address> {
   311→        match &self.precompiles {
   312→            PrecompilesKind::Builtin(precompiles) => Either::Left(precompiles.addresses()),
   313→            PrecompilesKind::Dynamic(dyn_precompiles) => {
   314→                Either::Right(dyn_precompiles.addresses.iter())
   315→            }
   316→        }
   317→    }
   318→
   319→    /// Gets a reference to the precompile at the given address.
   320→    ///
   321→    /// This method first checks the static precompile map, and if not found,
   322→    /// falls back to the dynamic lookup function (if set).
   323→    pub fn get(&self, address: &Address) -> Option<impl Precompile + '_> {
   324→        // First check static precompiles
   325→        let static_result = match &self.precompiles {
   326→            PrecompilesKind::Builtin(precompiles) => precompiles.get(address).map(Either::Left),
   327→            PrecompilesKind::Dynamic(dyn_precompiles) => {
   328→                dyn_precompiles.inner.get(address).map(Either::Right)
   329→            }
   330→        };
   331→
   332→        // If found in static precompiles, wrap in Left and return
   333→        if let Some(precompile) = static_result {
   334→            return Some(Either::Left(precompile));
   335→        }
   336→
   337→        // Otherwise, try the lookup function if available
   338→        let lookup = self.lookup.as_ref()?;
   339→        lookup.lookup(address).map(Either::Right)
   340→    }
   341→}
   342→
   343→impl From<EthPrecompiles> for PrecompilesMap {
   344→    fn from(value: EthPrecompiles) -> Self {
   345→        Self::from_static(value.precompiles)
   346→    }
   347→}
   348→
   349→impl core::fmt::Debug for PrecompilesMap {
   350→    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
   351→        match &self.precompiles {
   352→            PrecompilesKind::Builtin(_) => f.debug_struct("PrecompilesMap::Builtin").finish(),
   353→            PrecompilesKind::Dynamic(precompiles) => f
   354→                .debug_struct("PrecompilesMap::Dynamic")
   355→                .field("addresses", &precompiles.addresses)
   356→                .finish(),
   357→        }
   358→    }
   359→}
   360→
   361→impl<BlockEnv, TxEnv, CfgEnv, DB, Chain>
   362→    PrecompileProvider<Context<BlockEnv, TxEnv, CfgEnv, DB, Journal<DB>, Chain>> for PrecompilesMap
   363→where
   364→    BlockEnv: revm::context::Block,
   365→    TxEnv: revm::context::Transaction,
   366→    CfgEnv: revm::context::Cfg,
   367→    DB: Database,
   368→{
   369→    type Output = InterpreterResult;
   370→
   371→    fn set_spec(&mut self, _spec: CfgEnv::Spec) -> bool {
   372→        false
   373→    }
   374→
   375→    fn run(
   376→        &mut self,
   377→        context: &mut Context<BlockEnv, TxEnv, CfgEnv, DB, Journal<DB>, Chain>,
   378→        inputs: &CallInputs,
   379→    ) -> Result<Option<InterpreterResult>, String> {
   380→        // Get the precompile at the address
   381→        let Some(precompile) = self.get(&inputs.bytecode_address) else {
   382→            return Ok(None);
   383→        };
   384→
   385→        let mut result = InterpreterResult {
   386→            result: InstructionResult::Return,
   387→            gas: Gas::new(inputs.gas_limit),
   388→            output: Bytes::new(),
   389→        };
   390→
   391→        let (local, journal) = (&context.local, &mut context.journaled_state);
   392→
   393→        // Execute the precompile
   394→        let r;
   395→        let input_bytes = match &inputs.input {
   396→            CallInput::SharedBuffer(range) => {
   397→                // `map_or` does not work here as we use `r` to extend lifetime of the slice
   398→                // and return it.
   399→                #[allow(clippy::option_if_let_else)]
   400→                if let Some(slice) = local.shared_memory_buffer_slice(range.clone()) {
   401→                    r = slice;
   402→                    &*r
   403→                } else {
   404→                    &[]
   405→                }
   406→            }
   407→            CallInput::Bytes(bytes) => bytes.as_ref(),
   408→        };
   409→
   410→        let precompile_result = precompile.call(PrecompileInput {
   411→            data: input_bytes,
   412→            gas: inputs.gas_limit,
   413→            caller: inputs.caller,
   414→            value: inputs.call_value(),
   415→            internals: EvmInternals::new(journal, &context.block),
   416→            target_address: inputs.target_address,
   417→            bytecode_address: inputs.bytecode_address,
   418→        });
   419→
   420→        match precompile_result {
   421→            Ok(output) => {
   422→                let underflow = result.gas.record_cost(output.gas_used);
   423→                assert!(underflow, "Gas underflow is not possible");
   424→                result.result = if output.reverted {
   425→                    InstructionResult::Revert
   426→                } else {
   427→                    InstructionResult::Return
   428→                };
   429→                result.output = output.bytes;
   430→            }
   431→            Err(PrecompileError::Fatal(e)) => return Err(e),
   432→            Err(e) => {
   433→                result.result = if e.is_oog() {
   434→                    InstructionResult::PrecompileOOG
   435→                } else {
   436→                    InstructionResult::PrecompileError
   437→                };
   438→            }
   439→        };
   440→
   441→        Ok(Some(result))
   442→    }
   443→
   444→    fn warm_addresses(&self) -> Box<impl Iterator<Item = Address>> {
   445→        Box::new(self.addresses().copied())
   446→    }
   447→
   448→    fn contains(&self, address: &Address) -> bool {
   449→        self.get(address).is_some()
   450→    }
   451→}
   452→
   453→/// A mapping of precompile contracts that can be either static (builtin) or dynamic.
   454→///
   455→/// This is an optimization that allows us to keep using the static precompiles
   456→/// until we need to modify them, at which point we convert to the dynamic representation.
   457→#[derive(Clone)]
   458→enum PrecompilesKind {
   459→    /// Static builtin precompiles.
   460→    Builtin(Cow<'static, Precompiles>),
   461→    /// Dynamic precompiles that can be modified at runtime.
   462→    Dynamic(DynPrecompiles),
   463→}
   464→
   465→/// A dynamic precompile implementation that can be modified at runtime.
   466→#[derive(Clone)]
   467→pub struct DynPrecompile(pub(crate) Arc<dyn Precompile + Send + Sync>);
   468→
   469→impl DynPrecompile {
   470→    /// Creates a new [`DynPrecompiles`] with the given closure.
   471→    pub fn new<F>(id: PrecompileId, f: F) -> Self
   472→    where
   473→        F: Fn(PrecompileInput<'_>) -> PrecompileResult + Send + Sync + 'static,
   474→    {
   475→        Self(Arc::new((id, f)))
   476→    }
   477→
   478→    /// Creates a new [`DynPrecompiles`] with the given closure and [`Precompile::is_pure`]
   479→    /// returning `false`.
   480→    pub fn new_stateful<F>(id: PrecompileId, f: F) -> Self
   481→    where
   482→        F: Fn(PrecompileInput<'_>) -> PrecompileResult + Send + Sync + 'static,
   483→    {
   484→        Self(Arc::new(StatefulPrecompile((id, f))))
   485→    }
   486→
   487→    /// Flips [`Precompile::is_pure`] to `false`.
   488→    pub fn stateful(self) -> Self {
   489→        Self(Arc::new(StatefulPrecompile(self.0)))
   490→    }
   491→}
   492→
   493→impl core::fmt::Debug for DynPrecompile {
   494→    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
   495→        f.debug_struct("DynPrecompile").finish()
   496→    }
   497→}
