   525→/// Input for a precompile call.
   526→#[derive(Debug)]
   527→pub struct PrecompileInput<'a> {
   528→    /// Input data bytes.
   529→    pub data: &'a [u8],
   530→    /// Gas limit.
   531→    pub gas: u64,
   532→    /// Caller address.
   533→    pub caller: Address,
   534→    /// Value sent with the call.
   535→    pub value: U256,
   536→    /// Target address of the call. Would be the same as `bytecode_address` unless it's a
   537→    /// DELEGATECALL.
   538→    pub target_address: Address,
   539→    /// Bytecode address of the call.
   540→    pub bytecode_address: Address,
   541→    /// Various hooks for interacting with the EVM state.
   542→    pub internals: EvmInternals<'a>,
   543→}
   544→
   545→impl<'a> PrecompileInput<'a> {
   546→    /// Returns the calldata of the call.
   547→    pub const fn data(&self) -> &[u8] {
   548→        self.data
   549→    }
   550→
   551→    /// Returns the caller address of the call.
   552→    pub const fn caller(&self) -> &Address {
   553→        &self.caller
   554→    }
   555→
   556→    /// Returns the gas limit of the call.
   557→    pub const fn gas(&self) -> u64 {
   558→        self.gas
   559→    }
   560→
   561→    /// Returns the value of the call.
   562→    pub const fn value(&self) -> &U256 {
   563→        &self.value
   564→    }
   565→
   566→    /// Returns the target address of the call.
   567→    pub const fn target_address(&self) -> &Address {
   568→        &self.target_address
   569→    }
   570→
   571→    /// Returns the bytecode address of the call.
   572→    pub const fn bytecode_address(&self) -> &Address {
   573→        &self.bytecode_address
   574→    }
   575→
   576→    /// Returns whether the call is a direct call, i.e when precompile was called directly and not
   577→    /// via a DELEGATECALL/CALLCODE.
   578→    pub fn is_direct_call(&self) -> bool {
   579→        self.target_address == self.bytecode_address
   580→    }
   581→
   582→    /// Returns the [`EvmInternals`].
   583→    pub const fn internals(&self) -> &EvmInternals<'_> {
   584→        &self.internals
   585→    }
   586→
   587→    /// Returns a mutable reference to the [`EvmInternals`].
   588→    pub const fn internals_mut(&mut self) -> &mut EvmInternals<'a> {
   589→        &mut self.internals
   590→    }
   591→}
   592→
   593→/// Trait for implementing precompiled contracts.
   594→#[auto_impl::auto_impl(&, Arc)]
   595→pub trait Precompile {
   596→    /// Returns precompile ID.
   597→    fn precompile_id(&self) -> &PrecompileId;
   598→
   599→    /// Execute the precompile with the given input data, gas limit, and caller address.
   600→    fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult;
   601→
   602→    /// Returns whether the precompile is pure.
   603→    ///
   604→    /// A pure precompile has deterministic output based solely on its input.
   605→    /// Non-pure precompiles may produce different outputs for the same input
   606→    /// based on the current state or other external factors.
   607→    ///
   608→    /// # Default
   609→    ///
   610→    /// Returns `true` by default, indicating the precompile is pure
   611→    /// and its results should be cached as this is what most of the precompiles are.
   612→    ///
   613→    /// # Examples
   614→    ///
   615→    /// Override this method to return `false` for non-deterministic precompiles:
   616→    ///
   617→    /// ```ignore
   618→    /// impl Precompile for MyDeterministicPrecompile {
   619→    ///     fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult {
   620→    ///         // non-deterministic computation dependent on state
   621→    ///     }
   622→    ///
   623→    ///     fn is_pure(&self) -> bool {
   624→    ///         false // This precompile might produce different output for the same input
   625→    ///     }
   626→    /// }
   627→    /// ```
   628→    fn is_pure(&self) -> bool {
   629→        true
   630→    }
   631→}
   632→
   633→impl<F> Precompile for (PrecompileId, F)
   634→where
   635→    F: Fn(PrecompileInput<'_>) -> PrecompileResult + Send + Sync,
   636→{
   637→    fn precompile_id(&self) -> &PrecompileId {
   638→        &self.0
   639→    }
   640→
   641→    fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult {
   642→        self.1(input)
   643→    }
   644→}
   645→
   646→impl<F> Precompile for (&PrecompileId, F)
   647→where
   648→    F: Fn(PrecompileInput<'_>) -> PrecompileResult + Send + Sync,
   649→{
   650→    fn precompile_id(&self) -> &PrecompileId {
   651→        self.0
   652→    }
   653→
   654→    fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult {
   655→        self.1(input)
   656→    }
   657→}
   658→
   659→impl Precompile for revm::precompile::Precompile {
   660→    fn precompile_id(&self) -> &PrecompileId {
   661→        self.id()
   662→    }
   663→
   664→    fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult {
   665→        self.precompile()(input.data, input.gas)
   666→    }
   667→}
   668→
   669→impl<F> From<F> for DynPrecompile
   670→where
   671→    F: Fn(PrecompileInput<'_>) -> PrecompileResult + Send + Sync + 'static,
   672→{
   673→    fn from(f: F) -> Self {
   674→        Self::new(PrecompileId::Custom("closure".into()), f)
   675→    }
   676→}
   677→
   678→impl From<PrecompileFn> for DynPrecompile {
   679→    fn from(f: PrecompileFn) -> Self {
   680→        let p = move |input: PrecompileInput<'_>| f(input.data, input.gas);
   681→        p.into()
   682→    }
   683→}
   684→
   685→impl<F> From<(PrecompileId, F)> for DynPrecompile
   686→where
   687→    F: Fn(PrecompileInput<'_>) -> PrecompileResult + Send + Sync + 'static,
   688→{
   689→    fn from((id, f): (PrecompileId, F)) -> Self {
   690→        Self(Arc::new((id, f)))
   691→    }
   692→}
   693→
   694→impl From<(PrecompileId, PrecompileFn)> for DynPrecompile {
   695→    fn from((id, f): (PrecompileId, PrecompileFn)) -> Self {
   696→        let p = move |input: PrecompileInput<'_>| f(input.data, input.gas);
   697→        (id, p).into()
   698→    }
   699→}
   700→
   701→impl Precompile for DynPrecompile {
   702→    fn precompile_id(&self) -> &PrecompileId {
   703→        self.0.precompile_id()
   704→    }
   705→
   706→    fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult {
   707→        self.0.call(input)
   708→    }
   709→
   710→    fn is_pure(&self) -> bool {
   711→        self.0.is_pure()
   712→    }
   713→}
   714→
   715→impl<A: Precompile, B: Precompile> Precompile for Either<A, B> {
   716→    fn precompile_id(&self) -> &PrecompileId {
   717→        match self {
   718→            Self::Left(p) => p.precompile_id(),
   719→            Self::Right(p) => p.precompile_id(),
   720→        }
   721→    }
   722→
   723→    fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult {
   724→        match self {
   725→            Self::Left(p) => p.call(input),
   726→            Self::Right(p) => p.call(input),
   727→        }
   728→    }
   729→
   730→    fn is_pure(&self) -> bool {
   731→        match self {
   732→            Self::Left(p) => p.is_pure(),
   733→            Self::Right(p) => p.is_pure(),
   734→        }
   735→    }
   736→}
   737→
   738→struct StatefulPrecompile<P>(P);
   739→
   740→impl<P: Precompile> Precompile for StatefulPrecompile<P> {
   741→    fn precompile_id(&self) -> &PrecompileId {
   742→        self.0.precompile_id()
   743→    }
   744→
   745→    fn call(&self, input: PrecompileInput<'_>) -> PrecompileResult {
   746→        self.0.call(input)
   747→    }
   748→
   749→    fn is_pure(&self) -> bool {
   750→        false
   751→    }
   752→}
