   754→/// Trait for dynamically resolving precompile contracts.
   755→///
   756→/// This trait allows for runtime resolution of precompiles that aren't known
   757→/// at initialization time.
   758→pub trait PrecompileLookup: Send + Sync {
   759→    /// Looks up a precompile at the given address.
   760→    ///
   761→    /// Returns `Some(precompile)` if a precompile exists at the address,
   762→    /// or `None` if no precompile is found.
   763→    fn lookup(&self, address: &Address) -> Option<DynPrecompile>;
   764→}
   765→
   766→/// Implement PrecompileLookup for closure types
   767→impl<F> PrecompileLookup for F
   768→where
   769→    F: Fn(&Address) -> Option<DynPrecompile> + Send + Sync,
   770→{
   771→    fn lookup(&self, address: &Address) -> Option<DynPrecompile> {
   772→        self(address)
   773→    }
   774→}
