   249→        self.system_caller.with_state_hook(hook);
   250→    }
   251→
   252→    fn evm_mut(&mut self) -> &mut Self::Evm {
   253→        &mut self.evm
   254→    }
   255→
   256→    fn evm(&self) -> &Self::Evm {
   257→        &self.evm
   258→    }
   259→}
