   278→    /// [`ReceiptBuilder`].
   279→    pub const fn new(receipt_builder: R, spec: Spec, evm_factory: EvmFactory) -> Self {
   280→        Self { receipt_builder, spec, evm_factory }
   281→    }
   282→
