   284→    pub const fn receipt_builder(&self) -> &R {
   285→        &self.receipt_builder
   286→    }
   287→
   288→    /// Exposes the chain specification.
   289→    pub const fn spec(&self) -> &Spec {
   290→        &self.spec
   291→    }
   292→
   293→    /// Exposes the EVM factory.
